1	//! Rust port of `tests/test4.cpp`.
2	//!
3	//! Builds a polygon out of `n` overlapping axis-aligned squares, hands it to
4	//! the earcut triangulator and prints the resulting vertex indices separated
5	//! by spaces.
6	//!
7	//! Build standalone with `rustc -O test4.rs` (the modules below are pulled in
8	//! by path), or via `cargo build --release`, which builds the same file as the
9	//! `test4` binary target alongside the `earcut_test4` library.
10	
11	#[path = "src/cli.rs"]
12	mod cli;
13	
14	// The library exposes more than this one entry point needs; when test4.rs is
15	// compiled standalone with rustc the rest is legitimately unreachable.
16	#[allow(dead_code)]
17	#[path = "src/earcut/mod.rs"]
18	mod earcut;
19	
20	#[path = "src/polygon.rs"]
21	mod polygon;
22	
23	use std::io::Write;
24	
25	fn main() {
26	    let args: Vec<String> = std::env::args().collect();
27	
28	    let mut n: i32 = 4;
29	    if args.len() > 1 {
30	        n = cli::atoi(&args[1]);
31	    }
32	
33	    let polygon = polygon::overlapping_squares(n);
34	
35	    let indices = earcut::earcut(&polygon);
36	
37	    // `std::cout << idx << " "` for each index: no separator logic, no
38	    // trailing newline.
39	    let mut out = String::new();
40	    for idx in &indices {
41	        out.push_str(&idx.to_string());
42	        out.push(' ');
43	    }
44	
45	    let stdout = std::io::stdout();
46	    let mut handle = stdout.lock();
47	    let _ = handle.write_all(out.as_bytes());
48	    let _ = handle.flush();
49	}
