1	//! Pure-Rust, dependency-free port of the pieces of the C++ program
2	//! `tests/test4.cpp` that lived outside `main`: the `mapbox::earcut`
3	//! polygon triangulation, the polygon the test builds, and the C `atoi`
4	//! argument parsing.
5	//!
6	//! ```
7	//! use earcut_test4::{earcut::earcut, polygon::overlapping_squares};
8	//!
9	//! let indices = earcut(&overlapping_squares(1));
10	//! assert_eq!(indices, vec![2, 3, 0, 0, 1, 2]);
11	//! ```
12	
13	pub mod cli;
14	pub mod earcut;
15	pub mod polygon;
16	
17	/// Render a triangle index list the way `test4.cpp` does: every index followed
18	/// by a single space, with no trailing newline.
19	pub fn format_indices(indices: &[u32]) -> String {
20	    let mut out = String::new();
21	    for idx in indices {
22	        out.push_str(&idx.to_string());
23	        out.push(' ');
24	    }
25	    out
26	}
