fn run(n: i32) -> String {
    format_indices(&earcut(&overlapping_squares(n)))
}

fn check(cases: &[(i32, &str)]) {
    let mut failures = Vec::new();
    for &(n, expected) in cases {
        let actual = run(n);
        if actual != expected {
            failures.push(format!(
                "n={n}\n  expected: {expected:?}\n  actual:   {actual:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases diverged:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}
